BitmapFont::~BitmapFont()
{
    if (atlas_ != nullptr)
    {
        SDL_DestroyTexture(atlas_);
    }
}

bool BitmapFont::init(SDL_Renderer* renderer, int scale)
{
    if (renderer == nullptr || scale < 1)
    {
        return false;
    }
    scale_ = scale;
    const int texW = kGlyphCount * kCellW * scale_;
    const int texH = kCellH * scale_;

    SDL_Surface* surface =
        SDL_CreateRGBSurfaceWithFormat(0, texW, texH, 32, SDL_PIXELFORMAT_ARGB8888);
    if (surface == nullptr)
    {
        return false;
    }
    SDL_FillRect(surface, nullptr, 0); // transparent

    for (int g = 0; g < kGlyphCount; ++g)
    {
        for (int row = 0; row < kGlyphH; ++row)
        {
            const unsigned char bits = kGlyphs[g][row];
            for (int col = 0; col < kGlyphW; ++col)
            {
                if (((bits >> (kGlyphW - 1 - col)) & 1) == 0)
                {
                    continue;
                }
                SDL_Rect px;
                px.x = (g * kCellW + col) * scale_;
                px.y = row * scale_;
                px.w = scale_;
                px.h = scale_;
                SDL_FillRect(surface, &px, 0xFFFFFFFFu);
            }
        }
    }

    atlas_ = SDL_CreateTextureFromSurface(renderer, surface);
    SDL_FreeSurface(surface);
    if (atlas_ == nullptr)
    {
        return false;
    }
    SDL_SetTextureBlendMode(atlas_, SDL_BLENDMODE_BLEND);
    return true;
}

int BitmapFont::textWidth(const std::string& text) const
{
    return static_cast<int>(text.size()) * kCellW * scale_;
}

int BitmapFont::lineHeight() const
{
    return kCellH * scale_;
}

void BitmapFont::draw(SDL_Renderer* renderer, int x, int y, const std::string& text,
                      SDL_Color color) const
{
    if (atlas_ == nullptr || renderer == nullptr)
    {
        return;
    }
    SDL_SetTextureColorMod(atlas_, color.r, color.g, color.b);
    SDL_SetTextureAlphaMod(atlas_, color.a);

    int cursorX = x;
    for (char ch : text)
    {
        int code = static_cast<unsigned char>(ch);
        if (code < kFirstChar || code > kLastChar)
        {
            code = kFirstChar;
        }
        SDL_Rect src;
        src.x = (code - kFirstChar) * kCellW * scale_;
        src.y = 0;
        src.w = kGlyphW * scale_;
        src.h = kGlyphH * scale_;
        SDL_Rect dst;
        dst.x = cursorX;
        dst.y = y;
        dst.w = src.w;
        dst.h = src.h;
        SDL_RenderCopy(renderer, atlas_, &src, &dst);
        cursorX += kCellW * scale_;
    }
    SDL_SetTextureColorMod(atlas_, 255, 255, 255);
    SDL_SetTextureAlphaMod(atlas_, 255);
}

